#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long c;
    cin >> n >> c;

    vector<long long> p(n), t(n);
    for (auto& x : p) cin >> x;
    for (auto& x : t) cin >> x;

    long long limak = 0, radewoosh = 0, elapsed = 0;

    for (int i = 0; i < n; ++i) {
        elapsed += t[i];
        limak += max(0LL, p[i] - c * elapsed);
    }

    elapsed = 0;
    for (int i = n - 1; i >= 0; --i) {
        elapsed += t[i];
        radewoosh += max(0LL, p[i] - c * elapsed);
    }

    if (limak > radewoosh) cout << "Limak";
    else if (radewoosh > limak) cout << "Radewoosh";
    else cout << "Tie";

    return 0;
}

